import React, { Suspense } from 'react'
import { Routes, Route, Navigate } from 'react-router-dom'
import { AppRoutes } from '../../../Constants/docs'

// Wrapper component to handle async route loading
const AsyncRoute = ({ element, routePath }) => {
  const [Component, setComponent] = React.useState(null);
  const [loading, setLoading] = React.useState(true);

  React.useEffect(() => {
    setLoading(true);
    element().then(module => {
      setComponent(() => module.default);
      setLoading(false);
    });
  }, [element, routePath]);

  if (loading) {
    return <div>Loading...</div>;
  }

  return <Component key={routePath} />;
};

export default function DocAppRoutes() {
  return (
    <Routes>
      <Route path="/" element={<Navigate to="/walkthrough" replace />} />
      {AppRoutes.map((route) => (
        <Route 
          key={`route-${route.path}`} 
          path={route.path} 
          element={<AsyncRoute element={route.element} routePath={route.path} />} 
        />
      ))}
    </Routes>
  )
}